CREATE DATABASE IF NOT EXISTS compass CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE compass;
CREATE TABLE companies(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(160) NOT NULL,business_number VARCHAR(20) UNIQUE,industry VARCHAR(100) NOT NULL,ceo_name VARCHAR(80),email VARCHAR(160),website VARCHAR(255),memo TEXT,stage ENUM('자료 요청','미팅 예정','진단 진행','분석 완료','보고 완료') NOT NULL DEFAULT '자료 요청',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP)ENGINE=InnoDB;
CREATE TABLE documents(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,company_id BIGINT UNSIGNED NULL,grant_program_id BIGINT UNSIGNED NULL,original_name VARCHAR(255) NOT NULL,mime_type VARCHAR(100)NOT NULL,file_size BIGINT UNSIGNED NOT NULL,content_hash CHAR(64)NOT NULL,analysis_status ENUM('processing','completed','failed')NOT NULL DEFAULT'processing',analysis_version INT NOT NULL DEFAULT 1,analysis_json LONGTEXT,evidence_json LONGTEXT,error_message TEXT,analyzed_at DATETIME,created_by BIGINT UNSIGNED,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,INDEX idx_document_hash(content_hash),FOREIGN KEY(company_id)REFERENCES companies(id)ON DELETE CASCADE)ENGINE=InnoDB;
CREATE TABLE meetings(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,company_id BIGINT UNSIGNED NOT NULL,title VARCHAR(200) NOT NULL,meeting_at DATETIME NOT NULL,location VARCHAR(200),notes LONGTEXT,next_action TEXT,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(company_id)REFERENCES companies(id)ON DELETE CASCADE)ENGINE=InnoDB;
CREATE TABLE questions(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,company_id BIGINT UNSIGNED NOT NULL,meeting_id BIGINT UNSIGNED,category VARCHAR(80) NOT NULL,question TEXT NOT NULL,source ENUM('template','ai','manual')DEFAULT'manual',sort_order INT DEFAULT 0,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(company_id)REFERENCES companies(id)ON DELETE CASCADE,FOREIGN KEY(meeting_id)REFERENCES meetings(id)ON DELETE SET NULL)ENGINE=InnoDB;
CREATE TABLE answers(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,question_id BIGINT UNSIGNED NOT NULL,answer LONGTEXT NOT NULL,structured_json LONGTEXT,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(question_id)REFERENCES questions(id)ON DELETE CASCADE)ENGINE=InnoDB;
CREATE TABLE diagnostics(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,company_id BIGINT UNSIGNED NOT NULL,version INT DEFAULT 1,strategy_score DECIMAL(5,2),data_score DECIMAL(5,2),process_score DECIMAL(5,2),finance_score DECIMAL(5,2),execution_score DECIMAL(5,2),total_score DECIMAL(5,2),evidence_json LONGTEXT,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(company_id)REFERENCES companies(id)ON DELETE CASCADE)ENGINE=InnoDB;
CREATE TABLE kpis(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,company_id BIGINT UNSIGNED NOT NULL,name VARCHAR(160) NOT NULL,unit VARCHAR(30) NOT NULL,before_value DECIMAL(15,3),target_value DECIMAL(15,3),after_value DECIMAL(15,3),measured_at DATE,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(company_id)REFERENCES companies(id)ON DELETE CASCADE)ENGINE=InnoDB;
CREATE TABLE opportunities(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,company_id BIGINT UNSIGNED NOT NULL,title VARCHAR(200) NOT NULL,description TEXT,impact ENUM('low','medium','high')DEFAULT'medium',effort ENUM('low','medium','high')DEFAULT'medium',status VARCHAR(40)DEFAULT'identified',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(company_id)REFERENCES companies(id)ON DELETE CASCADE)ENGINE=InnoDB;
CREATE TABLE reports(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,company_id BIGINT UNSIGNED NOT NULL,type VARCHAR(60) NOT NULL,title VARCHAR(200) NOT NULL,content_json LONGTEXT,file_path VARCHAR(500),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(company_id)REFERENCES companies(id)ON DELETE CASCADE)ENGINE=InnoDB;
CREATE TABLE grant_programs(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,title VARCHAR(255) NOT NULL,agency VARCHAR(160),apply_start DATE,apply_end DATE,max_support_amount BIGINT UNSIGNED,announcement_url VARCHAR(500),source_document_id BIGINT UNSIGNED,requirements_json LONGTEXT,evaluation_json LONGTEXT,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(source_document_id)REFERENCES documents(id)ON DELETE SET NULL)ENGINE=InnoDB;
CREATE TABLE grant_matches(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,company_id BIGINT UNSIGNED NOT NULL,grant_program_id BIGINT UNSIGNED NOT NULL,eligibility ENUM('eligible','review','ineligible')NOT NULL DEFAULT'review',rule_score DECIMAL(5,2),semantic_score DECIMAL(5,2),total_score DECIMAL(5,2),matched_reasons LONGTEXT,gaps_json LONGTEXT,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(company_id)REFERENCES companies(id)ON DELETE CASCADE,FOREIGN KEY(grant_program_id)REFERENCES grant_programs(id)ON DELETE CASCADE,UNIQUE KEY uq_company_grant(company_id,grant_program_id))ENGINE=InnoDB;
CREATE TABLE users(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,email VARCHAR(190) NOT NULL UNIQUE,password_hash VARCHAR(255) NOT NULL,name VARCHAR(100) NOT NULL,role ENUM('admin','consultant','viewer')NOT NULL DEFAULT'viewer',is_active TINYINT(1)NOT NULL DEFAULT 1,last_login_at DATETIME,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP)ENGINE=InnoDB;
CREATE TABLE audit_logs(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED,action VARCHAR(100) NOT NULL,entity_type VARCHAR(80),entity_id BIGINT UNSIGNED,ip_address VARCHAR(45),detail_json LONGTEXT,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX idx_audit_created(created_at),FOREIGN KEY(user_id)REFERENCES users(id)ON DELETE SET NULL)ENGINE=InnoDB;
CREATE TABLE interview_sessions(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,company_id BIGINT UNSIGNED NOT NULL,grant_program_id BIGINT UNSIGNED NOT NULL,grant_match_id BIGINT UNSIGNED,question_version INT NOT NULL DEFAULT 1,status ENUM('draft','in_progress','completed','evaluated')NOT NULL DEFAULT'draft',questions_json LONGTEXT NOT NULL,created_by BIGINT UNSIGNED,meeting_at DATETIME,completed_at DATETIME,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(company_id)REFERENCES companies(id)ON DELETE CASCADE,FOREIGN KEY(grant_program_id)REFERENCES grant_programs(id)ON DELETE CASCADE,FOREIGN KEY(grant_match_id)REFERENCES grant_matches(id)ON DELETE SET NULL)ENGINE=InnoDB;
CREATE TABLE interview_answers(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,interview_session_id BIGINT UNSIGNED NOT NULL,question_key VARCHAR(80)NOT NULL,answer LONGTEXT NOT NULL,score DECIMAL(5,2),evidence TEXT,risk_level ENUM('low','medium','high'),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,UNIQUE KEY uq_session_question(interview_session_id,question_key),FOREIGN KEY(interview_session_id)REFERENCES interview_sessions(id)ON DELETE CASCADE)ENGINE=InnoDB;
CREATE TABLE company_decisions(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,company_id BIGINT UNSIGNED NOT NULL,grant_program_id BIGINT UNSIGNED NOT NULL,interview_session_id BIGINT UNSIGNED NOT NULL,eligibility_passed TINYINT(1)NOT NULL,diagnostic_score DECIMAL(5,2)NOT NULL,match_score DECIMAL(5,2)NOT NULL,interview_score DECIMAL(5,2)NOT NULL,final_score DECIMAL(5,2)NOT NULL,decision ENUM('recommend','conditional','hold','reject')NOT NULL,reasons_json LONGTEXT NOT NULL,risks_json LONGTEXT NOT NULL,required_actions_json LONGTEXT NOT NULL,current_scorecard_json LONGTEXT NOT NULL,improvement_plan_json LONGTEXT NOT NULL,to_be_json LONGTEXT NOT NULL,kpis_json LONGTEXT NOT NULL,decided_at DATETIME NOT NULL,decided_by BIGINT UNSIGNED,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(company_id)REFERENCES companies(id)ON DELETE CASCADE,FOREIGN KEY(grant_program_id)REFERENCES grant_programs(id)ON DELETE CASCADE,FOREIGN KEY(interview_session_id)REFERENCES interview_sessions(id)ON DELETE CASCADE)ENGINE=InnoDB;
